CREATE DATABASE IF NOT EXISTS logbook CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE logbook;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, username VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NULL, google_id VARCHAR(191) NULL UNIQUE, profile_image VARCHAR(500) NOT NULL DEFAULT '/api/uploads/profiles/SonoDefaultbald.jpg', role ENUM('user','admin') NOT NULL DEFAULT 'user', status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, last_login TIMESTAMP NULL, INDEX idx_email(email), INDEX idx_username(username));
CREATE TABLE log_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, log_date DATE NOT NULL, time_in TIME NULL, time_out TIME NULL, activity VARCHAR(255) NOT NULL, location VARCHAR(160) NULL, category VARCHAR(80) NOT NULL DEFAULT 'Other', remarks TEXT NULL, status ENUM('Completed','Ongoing','Cancelled') NOT NULL DEFAULT 'Completed', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_user_date(user_id, log_date), INDEX idx_category(category));
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(80) NOT NULL, description VARCHAR(255) NOT NULL, ip_address VARCHAR(45) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sender_id INT UNSIGNED NULL, title VARCHAR(160) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_notification_created(created_at));
CREATE TABLE notification_recipients (notification_id BIGINT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, read_at TIMESTAMP NULL, PRIMARY KEY (notification_id,user_id), FOREIGN KEY (notification_id) REFERENCES notifications(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_recipient_unread(user_id,read_at));
